import type { Prospect } from "@/domain/types";
import { LANE_META } from "@/domain/lanes";

/**
 * The prospect list.
 *
 * TWO HUNDRED AND ELEVEN REAL ORGANISATIONS WITHIN SEVEN MILES OF 245 W
 * BIRCH STREET, gathered in three passes that used different sources and
 * are labelled as such on every row. The third pass is described at the
 * WAVE 3 banner further down this file; everything immediately below
 * describes the first hundred and two.
 *
 * The first sixty-nine came out of the Google Places API on 11 August
 * 2026 and each carries the place id it came from, so any one of them
 * can be checked at source in about fifteen seconds.
 *
 * The next thirty-three are local retail, food, auto service and small
 * employers, researched by reading each organisation's own published
 * page or its landlord's tenant directory, then run through the US
 * Census Bureau geocoder for a coordinate. THOSE ROWS CARRY NO PLACE ID
 * AND THE FIELD IS ABSENT RATHER THAN FILLED. There was no Places call
 * in that pass, and a fabricated id on a row a reader might click is
 * worse than a missing one.
 *
 * THE EMAILS ARE THE PART WORTH BEING CAREFUL ABOUT.
 *
 * Thirty-five of these organisations publish a real email address on
 * their own website, and every one of the thirty-five carries the URL of
 * the page it was read off. Nothing here was pattern-guessed from a
 * domain name. There is no info@ in this file that was not actually seen
 * on an actual page, because one invented address is enough to make a
 * reader reasonably distrust every other figure on the screen, and the
 * value of this whole exercise is that the figures hold up.
 *
 * THE SECOND COHORT'S EMAIL RATIO IS FAR WORSE THAN THE FIRST'S, AND
 * THAT IS THE COMMERCIAL FINDING RATHER THAN A FAILURE OF THE SEARCH.
 * The schools, colleges, churches and professional practices in the
 * first pass published thirty addresses across sixty-nine
 * organisations, because institutions publish staff directories either
 * because they are obliged to or because it wins them business. The
 * second pass found five published addresses across forty-two
 * researched organisations. Franchise retail and chain auto service do
 * not publish a store-level email at all: a Crumbl franchisee routes
 * everything through a corporate form, and a Firestone store number has
 * no inbox behind it. So the entire local-retail-food lane is a go-see
 * lane, by the nature of how those businesses are run rather than by
 * anybody's preference, and the route sheet is the deliverable.
 *
 * Where there is no published address the row says so and carries the
 * contact form instead, or says the only route is the phone and the
 * door. That is not a hole in the data. An organisation with no
 * published email and a front desk IS a go-see, which is the activity
 * the job posting names first.
 *
 * THE ORGANISATION TYPE ON EVERY ROW WAS READ OFF THE ROW ITSELF.
 *
 * `orgType` is a second cut across the same hundred and two, and it is
 * not a synonym for the lane. The lane says how you reach them; the type
 * says where the yes lives. Seventeen are schools and colleges, which
 * buy on a published calendar and a purchase order. Twenty-eight are
 * branches, stores, franchised units or flagged properties, where the
 * person in the building cannot approve a party alone. Fifty-five are
 * single sites whose decision maker works in them, which includes both
 * a boba counter and a world headquarters, because in both cases the
 * approval chain tops out on the premises.
 *
 * Each row carries `orgTypeBasis`, a sentence naming the evidence that
 * put it where it is, and every one of those sentences was drawn from
 * something already on the row or in RESEARCH_local_businesses.md: a
 * decision maker title that says franchise owner or district manager, a
 * note recording that a catering line rings a corporate desk in another
 * county, a headcount basis that says single location.
 *
 * TWO ROWS SAY "unknown" AND THEY ARE NOT AN OVERSIGHT. The Amada
 * America facility and the Chase Suite hotel are both real, both
 * researched, and neither row says whether an evening out is signed on
 * the premises or somewhere above it. Guessing would have cost nothing
 * visible and would have made the other hundred worth less, so the
 * field says it does not know and the first visit can settle it.
 *
 * WHAT IS MODELED AND SAYS SO. Headcount ranges, buying windows and the
 * one-line fit note are judgements, not measurements. They carry
 * "modeled" provenance and a stated basis, and they render with a badge
 * that says as much. A headcount range with its reasoning attached is
 * honest in a way that a single confident number is not.
 *
 * WHAT WAS DELIBERATELY LEFT OUT. Round One Entertainment appeared in an
 * early pass as a Brea-headquartered corporate prospect, on the strength
 * of a business directory listing. Google Places puts Round One
 * Entertainment, Inc. at 12900 Park Plaza Drive in Cerritos, thirteen
 * miles away and outside this trade area. Two sources disagreed, so the
 * row came out. It would have been the most entertaining prospect on the
 * board and it is not on the board.
 *
 * Nine more organisations were held to that same standard in the second
 * pass and they are listed by name in EXCLUDED_FROM_BOARD at the foot of
 * this file, each with the reason. They are real, they were researched,
 * and they are not on the board. Publishing the list of what was thrown
 * away is the only thing that makes the ninety-three per cent that
 * stayed worth anything. Sixteen more joined that list in the third
 * pass, which is twenty-five names published as removed against two
 * hundred and eleven published as real.
 *
 * EVERY ROW NOW CARRIES A `segment`, WHICH IS A TWO-DIGIT NAICS SECTOR.
 * That is a third cut across the same board and a different question
 * from the lane: the lane says how you reach somebody, `orgType` says
 * where the yes lives, and the sector says what they do for a living,
 * which is what decides whether the occasion exists at all. The
 * reasoning, and the one place this board deliberately bends the federal
 * classification, is in `domain/segments.ts`.
 */

